1	import { policyBasePremium, type Item } from "./price-list.js";
2	import { itemRiskSurcharges } from "./item-risk.js";
3	import { policyModifiers } from "./customer-standing.js";
4	import { type Customer } from "./customer.js";
5	
6	export type { Item, Customer };
7	
8	/** MHPCO adds a flat processing fee to every premium, at the very end. */
9	const PROCESSING_FEE_G = 5;
10	
11	/**
12	 * MHPCO rounds every final amount in its own favour: a premium the customer
13	 * owes is rounded up. Only the final amount is rounded; intermediate amounts
14	 * are kept as fractions.
15	 */
16	function roundPremiumInMHPCOFavour(premium: number): number {
17	  return Math.ceil(premium);
18	}
19	
20	/**
21	 * Assembles the bill in the order the office bills it: the price-list base
22	 * premium of the policy, the risk surcharges its individual items carry, the
23	 * modifiers rated on the policy as a whole, and finally the processing fee.
24	 *
25	 * Each of those amounts is ruled on elsewhere; this function only knows the
26	 * order they are applied in and that the total is rounded once, at the end.
27	 */
28	export function quote(customer: Customer, items: readonly Item[]): number {
29	  const policyBase = policyBasePremium(items);
30	  const premium =
31	    policyBase +
32	    itemRiskSurcharges(items) +
33	    policyModifiers(customer, policyBase) +
34	    PROCESSING_FEE_G;
35	  return roundPremiumInMHPCOFavour(premium);
36	}
