1	/**
2	 * MHPCO's risk rating of a single insured item.
3	 *
4	 * This module owns one underwriting policy: which properties of an item the
5	 * office considers risky, and what surcharge each of those risks carries. Such
6	 * a risk surcharge is always charged on the base premium of the affected item
7	 * alone, never on the policy total — that is what makes it item-specific and
8	 * keeps it apart from the policy-wide modifiers that depend on the customer's
9	 * history rather than on the item.
10	 */
11	
12	import { itemBasePremium, type Item } from "./price-list.js";
13	
14	const PERCENT = 100;
15	
16	/** A risky property of an item, and the surcharge MHPCO charges for it. */
17	interface RiskRating {
18	  readonly appliesTo: (item: Item) => boolean;
19	  readonly surchargePercent: number;
20	}
21	
22	/**
23	 * The office's register of item risks. Each entry is an independent ruling:
24	 * further risks are added here, and the rate of an existing one is revised
25	 * here, without touching how a premium is assembled.
26	 */
27	const HIGHLY_ENCHANTED_FROM = 5;
28	
29	const RISK_RATINGS: readonly RiskRating[] = [
30	  { appliesTo: (item) => item.cursed === true, surchargePercent: 50 },
31	  {
32	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGHLY_ENCHANTED_FROM,
33	    surchargePercent: 30,
34	  },
35	];
36	
37	/** The total item-specific risk surcharge MHPCO charges for one item. */
38	export function itemRiskSurcharge(item: Item): number {
39	  const basePremium = itemBasePremium(item);
40	  return RISK_RATINGS.filter((rating) => rating.appliesTo(item)).reduce(
41	    (total, rating) => total + (basePremium * rating.surchargePercent) / PERCENT,
42	    0,
43	  );
44	}
45	
46	/** The item-specific risk surcharges of all items a policy covers. */
47	export function itemRiskSurcharges(items: readonly Item[]): number {
48	  return items.reduce((total, item) => total + itemRiskSurcharge(item), 0);
49	}
