1	/**
2	 * The MHPCO price list: what each insured thing costs before any modifier.
3	 *
4	 * This module owns catalogue knowledge only — which item types the office
5	 * recognises and the base premium it charges for them. It deliberately knows
6	 * nothing about surcharges, discounts, the processing fee or rounding: those
7	 * are underwriting policy and change for entirely different reasons.
8	 */
9	
10	export interface Item {
11	  readonly type: string;
12	  readonly cursed?: boolean;
13	  readonly enchantment?: number;
14	}
15	
16	/** The MHPCO price list for main items: base premium in G per item type. */
17	const MAIN_ITEM_BASE_PREMIUM_G: Readonly<Record<string, number>> = {
18	  sword: 100,
19	  amulet: 60,
20	  staff: 80,
21	  potion: 40,
22	};
23	
24	/**
25	 * Components — runes, moonstones and their kin — are not listed individually on
26	 * the main price list. MHPCO charges one uniform rate per component.
27	 */
28	const COMPONENT_BASE_PREMIUM_G = 25;
29	
30	const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];
31	
32	function isComponent(item: Item): boolean {
33	  return COMPONENT_TYPES.includes(item.type);
34	}
35	
36	/**
37	 * MHPCO offers a building block of exactly 3 alike components — components of
38	 * the same type — at a special base premium instead of the per-component rate.
39	 */
40	const BLOCK_SIZE = 3;
41	const BLOCK_BASE_PREMIUM_G = 60;
42	
43	/**
44	 * The base premium of a single item, as the item-specific risk surcharges see
45	 * it: the price list rate for the item on its own, before any building-block
46	 * discount the policy as a whole may earn.
47	 */
48	export function itemBasePremium(item: Item): number {
49	  return isComponent(item) ? COMPONENT_BASE_PREMIUM_G : mainItemBasePremium(item);
50	}
51	
52	/** The base premium of a single main item according to the MHPCO price list. */
53	function mainItemBasePremium(item: Item): number {
54	  return MAIN_ITEM_BASE_PREMIUM_G[item.type];
55	}
56	
57	/** The base premium MHPCO charges for a number of alike components. */
58	function alikeComponentsBasePremium(count: number): number {
59	  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM_G : count * COMPONENT_BASE_PREMIUM_G;
60	}
61	
62	/**
63	 * MHPCO reads "alike" as "of the same type": two runes and a moonstone are not
64	 * three alike components, and a policy covering 3 runes and 3 moonstones earns
65	 * two separate building blocks. Grouping components by type is therefore the
66	 * office's ruling on what counts as alike, and the sizes of these groups are
67	 * what the block rule is applied to.
68	 */
69	function alikeComponentGroupSizes(components: readonly Item[]): number[] {
70	  const sizeByType = new Map<string, number>();
71	  for (const component of components) {
72	    sizeByType.set(component.type, (sizeByType.get(component.type) ?? 0) + 1);
73	  }
74	  return [...sizeByType.values()];
75	}
76	
77	/**
78	 * Components are priced per group of alike components, not per item: MHPCO
79	 * gathers the alike ones together first so that a building block can be
80	 * recognised, then prices each group on its own.
81	 */
82	function componentsBasePremium(components: readonly Item[]): number {
83	  return alikeComponentGroupSizes(components).reduce(
84	    (total, groupSize) => total + alikeComponentsBasePremium(groupSize),
85	    0,
86	  );
87	}
88	
89	/**
90	 * The sum of the base premiums of all insured items, before any modifier.
91	 *
92	 * Main items are priced one by one straight off the price list; components are
93	 * handed to the component pricing rules as a group, because their price depends
94	 * on how many alike ones the policy covers.
95	 */
96	export function policyBasePremium(items: readonly Item[]): number {
97	  const mainItemsTotal = items
98	    .filter((item) => !isComponent(item))
99	    .reduce((sum, item) => sum + mainItemBasePremium(item), 0);
100	  return mainItemsTotal + componentsBasePremium(items.filter(isComponent));
101	}
