1	/**
2	 * The customer whose standing with MHPCO the policy-wide modifiers are rated
3	 * against: how long they have been with the office, and how many contracts they
4	 * already hold.
5	 */
6	export interface Customer {
7	  readonly yearsWithMHPCO: number;
8	  readonly previousContracts: number;
9	}
