1	import { describe, expect, it } from "vitest";
2	import { quote, type Customer } from "./claim-office.js";
3	
4	/**
5	 * A customer whose history contributes no policy-wide modifier: brand new to
6	 * MHPCO, so neither the loyalty discount nor the follow-up contract discount
7	 * applies. Quotes for this customer show base premiums and the first-insurance
8	 * surcharge on their own.
9	 */
10	const NEWCOMER: Customer = { yearsWithMHPCO: 0, previousContracts: 0 };
11	
12	describe("MHPCO Claim Office", () => {
13	  // --- Quote: processing fee and empty policy ---
14	  it("quotes an empty item list as premium 5 G (processing fee only)", () => {
15	    expect(quote(NEWCOMER, [])).toBe(5);
16	  });
17	
18	  // --- Quote: base premiums per main item type (price list catalogue) ---
19	  it("quotes a single sword with no modifiers -- base 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
20	    expect(quote(NEWCOMER, [{ type: "sword" }])).toBe(115);
21	  });
22	  it("quotes a single amulet with no modifiers -- base 60 G + 6 G first insurance + 5 G fee = 71 G", () => {
23	    expect(quote(NEWCOMER, [{ type: "amulet" }])).toBe(71);
24	  });
25	  it("quotes a single staff with no modifiers -- base 80 G + 8 G first insurance + 5 G fee = 93 G", () => {
26	    expect(quote(NEWCOMER, [{ type: "staff" }])).toBe(93);
27	  });
28	  it("quotes a single potion with no modifiers -- base 40 G + 4 G first insurance + 5 G fee = 49 G", () => {
29	    expect(quote(NEWCOMER, [{ type: "potion" }])).toBe(49);
30	  });
31	
32	  // --- Quote: component base premiums and building blocks ---
33	  it("quotes a single rune -- component base premium 25 G", () => {
34	    // 25 base + 2.5 first insurance + 5 fee = 32.5 -> rounded up in MHPCO's favour
35	    expect(quote(NEWCOMER, [{ type: "rune" }])).toBe(33);
36	  });
37	  it("quotes a single moonstone -- component base premium 25 G", () => {
38	    expect(quote(NEWCOMER, [{ type: "moonstone" }])).toBe(33);
39	  });
40	  it("quotes 2 runes -- base premium 50 G (no block)", () => {
41	    // 50 base + 5 first insurance + 5 fee = 60
42	    expect(quote(NEWCOMER, [{ type: "rune" }, { type: "rune" }])).toBe(60);
43	  });
44	  it("quotes 3 runes -- base premium 60 G (block applies)", () => {
45	    // 60 block base + 6 first insurance + 5 fee = 71
46	    const runes = [{ type: "rune" }, { type: "rune" }, { type: "rune" }];
47	    expect(quote(NEWCOMER, runes)).toBe(71);
48	  });
49	  it("quotes 4 runes -- base premium 100 G (no block; block requires exactly 3)", () => {
50	    // 100 base + 10 first insurance + 5 fee = 115
51	    const runes = Array.from({ length: 4 }, () => ({ type: "rune" }));
52	    expect(quote(NEWCOMER, runes)).toBe(115);
53	  });
54	  it("quotes 7 runes -- base premium 175 G (no block; 7 is not exactly 3)", () => {
55	    // 175 base + 17.5 first insurance + 5 fee = 197.5 -> 198 rounded up
56	    const runes = Array.from({ length: 7 }, () => ({ type: "rune" }));
57	    expect(quote(NEWCOMER, runes)).toBe(198);
58	  });
59	  it("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: alike means same type)", () => {
60	    // 75 base + 7.5 first insurance + 5 fee = 87.5 -> 88 rounded up
61	    const items = [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }];
62	    expect(quote(NEWCOMER, items)).toBe(88);
63	  });
64	  it("quotes 3 runes + 3 moonstones -- base premium 120 G (two separate blocks of alike components)", () => {
65	    // 60 + 60 base + 12 first insurance + 5 fee = 137
66	    const items = [
67	      { type: "rune" }, { type: "rune" }, { type: "rune" },
68	      { type: "moonstone" }, { type: "moonstone" }, { type: "moonstone" },
69	    ];
70	    expect(quote(NEWCOMER, items)).toBe(137);
71	  });
72	
73	  // --- Quote: item-specific modifiers ---
74	  it("adds a 50% curse surcharge to the cursed item's base premium", () => {
75	    // 100 base + 50 curse + 10 first insurance (10% of the 100 G base) + 5 fee = 165
76	    expect(quote(NEWCOMER, [{ type: "sword", cursed: true }])).toBe(165);
77	  });
78	  it("adds a 30% high-enchantment surcharge at enchantment exactly 5", () => {
79	    // 100 base + 30 high enchantment + 10 first insurance + 5 fee = 145
80	    expect(quote(NEWCOMER, [{ type: "sword", enchantment: 5 }])).toBe(145);
81	  });
82	  it("adds no high-enchantment surcharge at enchantment 4", () => {
83	    // 100 base + 10 first insurance + 5 fee = 115
84	    expect(quote(NEWCOMER, [{ type: "sword", enchantment: 4 }])).toBe(115);
85	  });
86	  it("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5", () => {
87	    // 100 base + 50 curse + 30 high enchantment + 10 first insurance + 5 fee = 195
88	    expect(quote(NEWCOMER, [{ type: "sword", cursed: true, enchantment: 5 }])).toBe(195);
89	  });
90	  it("applies the curse surcharge only to the cursed item, not the policy total -- cursed sword + plain amulet -> 210 G before policy modifiers and fee", () => {
91	    // 160 policy base + 50 curse (50% of the sword's 100, not of 160) = 210
92	    // + 16 first insurance (10% of 160) + 5 fee = 231
93	    const items = [{ type: "sword", cursed: true }, { type: "amulet" }];
94	    expect(quote(NEWCOMER, items)).toBe(231);
95	  });
96	
97	  // --- Quote: policy-wide modifiers ---
98	  it("applies the 20% loyalty discount at exactly 2 years with MHPCO", () => {
99	    // 100 base - 20 loyalty + 10 first insurance + 5 fee = 95
100	    const loyal = { yearsWithMHPCO: 2, previousContracts: 0 };
101	    expect(quote(loyal, [{ type: "sword" }])).toBe(95);
102	  });
103	  it.todo("applies no loyalty discount at 1 year with MHPCO");
104	  it.todo("applies the 10% first-insurance surcharge to every item in every quote, regardless of customer history");
105	  it.todo("applies a 15% follow-up discount on the customer's second quote");
106	  it.todo("applies no follow-up discount on the customer's first quote");
107	  it.todo("adds the 5 G processing fee at the very end, after all other modifiers");
108	
109	  // --- Quote: rounding in MHPCO's favor ---
110	  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favor)");
111	  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");
112	
113	  // --- Quote: integration examples ---
114	  it.todo("integration: newcomer (0 years, first contract) with a cursed steel sword enchantment 3 -- premium 165 G");
115	  it.todo("integration: 3-year customer's second quote, cursed steel sword enchantment 7 -- premium 160 G");
116	
117	  // --- Quote: rejection ---
118	  it.todo("rejects a quote containing an unknown item type -- CLI exits non-zero, error on stderr, no results on stdout");
119	
120	  // --- Claim: standard reimbursement and deductible ---
121	  it.todo("pays out full damage minus the 100 G deductible for a steel sword enchantment 3, damage 500 G -- payout 400 G");
122	  it.todo("pays out full damage minus the 100 G deductible for a rune (no enchantment, no material), damage 200 G -- payout 100 G");
123	  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G -> payout 600 G");
124	
125	  // --- Claim: special clauses ---
126	  it.todo("reimburses 50% of damage for enchantment exactly 8 -- dragon sword enchantment 8, damage 1000 G -> payout 400 G");
127	  it.todo("reimburses dragon material fully -- dragon sword enchantment 5, damage 800 G -> payout 700 G");
128	  it.todo("prefers the 50% rule when both clauses apply -- dragon sword enchantment 9, damage 1000 G -> payout 400 G");
129	  it.todo("applies only the high-enchantment clause for a steel sword enchantment 9, damage 1000 G -> payout 400 G");
130	
131	  // --- Claim: insurance sum and cap ---
132	  it.todo("caps payout at twice the insurance sum -- single sword policy: insurance sum 1000 G, cap 2000 G");
133	  it.todo("sums insurance values across items -- sword + amulet: insurance sum 1600 G, cap 3200 G");
134	  it.todo("computes insurance sum 2000 G and cap 4000 G for a policy covering two swords");
135	  it.todo("computes insurance sum 1750 G and cap 3500 G for a sword + 3 runes (block affects premium only)");
136	  it.todo("bases the cap on unmodified insurance value -- cursed sword (premium 165 G) still has cap 2000 G");
137	  it.todo("reports remainingCap after a claim -- sword policy, claim 1500 G -> payout 1400 G, remainingCap 600 G");
138	  it.todo("reduces a later payout to the remaining cap -- second claim of 1500 G -> payout 600 G, remainingCap 0 G");
139	
140	  // --- Claim: multiple items of the same type ---
141	  it.todo("treats each damage entry of the same itemType as a separate damage with its own deductible -- two swords damaged");
142	  it.todo("rejects a claim with more damage entries of a type than the policy covers -- CLI exits non-zero, error on stderr");
143	
144	  // --- Claim: rounding in MHPCO's favor ---
145	  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favor)");
146	
147	  // --- Claim: rejection ---
148	  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured) -- CLI exits non-zero, error on stderr");
149	  it.todo("rejects a claim referencing an unknown item type -- CLI exits non-zero, error on stderr");
150	  it.todo("rejects a claim with a negative damage amount (-200) -- CLI exits non-zero, error on stderr");
151	
152	  // --- CLI: scenario protocol ---
153	  it.todo("CLI reads a JSON scenario from stdin and writes {results: [...]} to stdout in step order");
154	  it.todo("CLI resolves a claim step's policy field to the zero-based index of the earlier quote step");
155	  it.todo("CLI processes the schema example -- amulet quote then 200 G amulet claim -- producing a premium and a payout/remainingCap result");
156	});
